/**
 * The help card beside the questions of FaqSplit: a title, a line of text, the ways to reach the team (icon,
 * name, one line) and a link.
 */
import { For, type JSX } from "solid-js";
import { Block, Box, Button, List, ListItem, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import type { Question, FaqSplitLabels } from "../blocks/faq-split.types";
import type { Feature } from "../blocks/feature-grid.types";

export type FaqHelpProps = {
  labels: FaqSplitLabels;
  channels: Feature[];
  landmarkLabel?: string;
};

export function FaqHelp({ labels, channels, landmarkLabel }: FaqHelpProps) {
  return (
    <Block
      tag="aside"
      class="rounded bg-card inset-ring inset-ring-border flex flex-col gap-6 p-6"
      aria-label={(landmarkLabel ?? labels.asideTitle)}
      data-testid="faq-help"
    >
      <Stack gap="2">
        <Text size="lg" weight="semibold">
          {labels.asideTitle}
        </Text>
        <Text size="sm" class="text-muted-foreground">
          {labels.asideText}
        </Text>
      </Stack>
      <List class="m-0 flex list-none flex-col gap-4 p-0">
        <For each={channels ?? []}>{(c) => (
          <ListItem class="flex items-start gap-4" data-testid="faq-channel">
            <Box class="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
              <LucideIcon name={c.icon} size={20} />
            </Box>
            <Stack gap="0">
              <Text size="sm" weight="semibold">
                {c.title}
              </Text>
              <Text size="xs" class="text-muted-foreground">
                {c.text}
              </Text>
            </Stack>
          </ListItem>
        )}</For>
      </List>
      <Button variant="link" size="sm" class="gap-2 px-0 font-medium">
        {labels.asideCta}
        <LucideIcon name="arrow-right" size={16} />
      </Button>
    </Block>
  );
}
